static float rf_tree_predict(
    const float *features,
    const int32_t *left,
    const int32_t *right,
    const int16_t *feature,
    const float *threshold,
    const float *value0,
    const float *value1
) {
    int32_t node = 0;

    while (left[node] != -1) {

        int16_t f = feature[node];

        if (features[f] <= threshold[node])
            node = left[node];
        else
            node = right[node];
    }

    return value1[node];
}


